module UMST.Chem.GroundStates where

type Occupancy = (Int, Int, Int)

capacity :: (Int, Int) -> Int
capacity (_, l) = 2 * (2 * l + 1)

madelungRank :: (Int, Int) -> Int
madelungRank (n, l) = (n + l) * 8 + n

madelungOrder :: [(Int, Int)]
madelungOrder = [(1, 0), (2, 0), (2, 1), (3, 0), (3, 1), (4, 0), (3, 2), (4, 1), (5, 0), (4, 2), (5, 1), (6, 0), (4, 3), (5, 2), (6, 1), (7, 0), (5, 3), (6, 2), (7, 1), (6, 3), (7, 2), (7, 3)]

fill :: [(Int, Int)] -> Int -> [Occupancy]
fill [] _ = []
fill ((n, l) : rest) z
  | z <= 0 = []
  | otherwise = let k = min (capacity (n, l)) z in (n, l, k) : fill rest (z - k)

madelung :: Int -> [Occupancy]
madelung = fill madelungOrder

electrons :: [Occupancy] -> Int
electrons c = sum [k | (_, _, k) <- c]

withinCapacity :: [Occupancy] -> Bool
withinCapacity = all (\(n, l, k) -> k <= capacity (n, l))

